import React, { useEffect, useState } from "react";
import axios from "axios";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement);

function App() {
  const [data, setData] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 3000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/data");

      // 🔥 filter data aneh
      const cleanData = res.data.filter(d => d.waktu !== "None");

      setData(cleanData);
      setLoading(false);

      console.log("DATA:", cleanData);

    } catch (err) {
      console.log("ERROR:", err);
    }
  };

  const latest = data.length > 0 ? data[0] : null;

  const chartData = {
    labels: data.map(d => d.waktu).reverse(),
    datasets: [
      {
        label: "Jumlah Orang",
        data: data.map(d => d.jumlah_orang).reverse(),
        borderColor: "#22c55e"
      }
    ]
  };

  const getColor = (kondisi) => {
    if (kondisi === "PEMBOROSAN" || kondisi === "PERINGATAN") {
      return "red";
    }
    return "#22c55e";
  };

  return (
    <div style={{ display: "flex", background: "#0f172a", color: "white", minHeight: "100vh" }}>

      {/* SIDEBAR */}
      <div style={{ width: 220, padding: 20, background: "#1e293b" }}>
        <h2>Hematrik</h2>
        <p onClick={() => setPage("dashboard")}>Dashboard</p>
        <p onClick={() => setPage("monitoring")}>Monitoring</p>
        <p onClick={() => setPage("history")}>History</p>
      </div>

      {/* CONTENT */}
      <div style={{ flex: 1, padding: 20 }}>

        {/* LOADING */}
        {loading && <h2>Loading data...</h2>}

        {/* DASHBOARD */}
        {!loading && page === "dashboard" && latest && (
          <>
            <h1>Dashboard Monitoring</h1>

            <div style={{
              padding: 15,
              borderRadius: 10,
              marginBottom: 20,
              background: latest.kondisi === "PEMBOROSAN" || latest.kondisi === "PERINGATAN"
                ? "#7f1d1d"
                : "#065f46"
            }}>
              {latest.notifikasi}
            </div>

            <div style={{ display: "flex", gap: 20 }}>
              <div style={{ background:"#1e293b", padding:20 }}>
                <h3>People</h3>
                <h1>{latest.jumlah_orang}</h1>
              </div>

              <div style={{ background:"#1e293b", padding:20 }}>
                <h3>Listrik</h3>
                <h1>{latest.status_listrik}</h1>
              </div>

              <div style={{ background:"#1e293b", padding:20 }}>
                <h3>Kondisi</h3>
                <h1 style={{ color: getColor(latest.kondisi) }}>
                  {latest.kondisi}
                </h1>
              </div>
            </div>

            <Line data={chartData} />
          </>
        )}

        {/* MONITORING */}
        {!loading && page === "monitoring" && latest && (
          <>
            <h1>Monitoring</h1>
            <img src={`http://127.0.0.1:8000/${latest.gambar}`} width="400" alt="" />
            <h2>{latest.jumlah_orang} Orang</h2>
          </>
        )}

        {/* HISTORY */}
        {!loading && page === "history" && (
          <>
            <h1>History</h1>
            <table>
              <thead>
                <tr>
                  <th>Waktu</th>
                  <th>Orang</th>
                  <th>Listrik</th>
                  <th>Kondisi</th>
                </tr>
              </thead>
              <tbody>
                {data.map(d => (
                  <tr key={d.id}>
                    <td>{d.waktu}</td>
                    <td>{d.jumlah_orang}</td>
                    <td>{d.status_listrik}</td>
                    <td style={{ color: getColor(d.kondisi) }}>
                      {d.kondisi}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

      </div>
    </div>
  );
}

export default App;
